package com.hbm.client.reactor.rbmk.fuel;
import com.hbm.machine.reactor.rbmk.fuel.*;import mezz.jei.api.*;import mezz.jei.api.constants.VanillaTypes;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.ingredients.subtypes.*;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.registration.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;
@JeiPlugin public final class RbmkFuelJeiPlugin implements IModPlugin {
 private static final RecipeType<RbmkFuelViews.View> DISASSEMBLY=RecipeType.create("hbm","rbmk_disassembly",RbmkFuelViews.View.class),COOLING=RecipeType.create("hbm","rbmk_fuel_cooling",RbmkFuelViews.View.class);@Override public ResourceLocation getPluginUid(){return ResourceLocation.parse("hbm:rbmk_fuel");}@Override public void registerCategories(IRecipeCategoryRegistration event){var helper=event.getJeiHelpers().getGuiHelper();event.addRecipeCategories(new Category(helper,false),new Category(helper,true));}@Override public void registerRecipes(IRecipeRegistration event){event.addRecipes(DISASSEMBLY,RbmkFuelViews.disassembly());event.addRecipes(COOLING,RbmkFuelViews.cooling());}@Override public void registerRecipeCatalysts(IRecipeCatalystRegistration event){event.addRecipeCatalyst(RbmkFuelViews.catalyst(false),DISASSEMBLY);event.addRecipeCatalyst(RbmkFuelViews.catalyst(true),COOLING);}@Override public void registerExtraIngredients(IExtraIngredientRegistration event){event.addExtraIngredients(VanillaTypes.ITEM_STACK,RbmkFuelContent.allStacks());}
 @Override public void registerItemSubtypes(ISubtypeRegistration event){for(var holder:RbmkFuelContent.PELLETS){var item=holder.get();event.registerSubtypeInterpreter(item,new ISubtypeInterpreter<ItemStack>(){public Object getSubtypeData(ItemStack stack,UidContext context){return item.metadata(stack);}public String getLegacyStringSubtypeInfo(ItemStack stack,UidContext context){return getSubtypeData(stack,context).toString();}});}for(var holder:RbmkFuelContent.RODS)event.registerSubtypeInterpreter(holder.get(),new ISubtypeInterpreter<ItemStack>(){public Object getSubtypeData(ItemStack stack,UidContext context){return RbmkFuelViews.hot(stack);}public String getLegacyStringSubtypeInfo(ItemStack stack,UidContext context){return getSubtypeData(stack,context).toString();}});}
 private static final class Category implements IRecipeCategory<RbmkFuelViews.View>{final boolean cooling;final IDrawable background,icon;Category(IGuiHelper helper,boolean cooling){this.cooling=cooling;background=helper.createBlankDrawable(166,65);icon=helper.createDrawableItemStack(RbmkFuelViews.catalyst(cooling));}@Override public RecipeType<RbmkFuelViews.View> getRecipeType(){return cooling?COOLING:DISASSEMBLY;}@Override public Component getTitle(){return Component.translatable(cooling?"rbmk.cooling":"rbmk.disassembly");}@Override public IDrawable getBackground(){return background;}@Override public IDrawable getIcon(){return icon;}@Override public void setRecipe(IRecipeLayoutBuilder builder,RbmkFuelViews.View recipe,IFocusGroup focus){builder.addSlot(RecipeIngredientRole.INPUT,48,24).addItemStack(recipe.input());builder.addSlot(RecipeIngredientRole.OUTPUT,102,24).addItemStack(recipe.output());builder.addSlot(RecipeIngredientRole.CATALYST,75,31).addItemStack(RbmkFuelViews.catalyst(cooling));}@Override public void draw(RbmkFuelViews.View recipe,IRecipeSlotsView slots,GuiGraphics graphics,double x,double y){RbmkFuelViews.draw(graphics,0,0);}}
}
